    "about.title": "پیارا پاکستان دے بارے",
    "about.subtitle": "پاکستان دی ودھݨ آلی ڈیجیٹل مارکیٹ پلیس — ہر کیٹیگری وچ تصدیق شدہ خریداراں تے ویچݨ آلیاں کوں جوڑیندی اے، گھریلو سروسز کنوں مقامی دکاناں تئیں۔",
    "about.missionTitle": "اساݙا مشن",
    "about.missionText": "پیارا پاکستان دا مقصد پاکستان وچ کیہڑے وی کیتے خریدݨ یا ویچݨ سوکھا تے محفوظ بݨاوݨ اے — چاہے او الیکٹریشن بک کرݨا ہووے، اے سی دی مرمت آلا لبھݨا ہووے، یا مقامی دکان دے پراڈکٹ ڈیکھݨے ہون۔ اساں تصدیق کوں پلیٹ فارم دے بنیادی حصے وچ شامل کیتا اے تاں جو خریدار اوہناں تے بھروسہ کر سڳھن جنہاں نال او ڈیل کر رہے ہن۔",
    "about.visionTitle": "اساݙا وژن",
    "about.visionText": "پاکستان دی سبھ کنوں قابلِ بھروسہ ملٹی کیٹیگری مارکیٹ پلیس بݨنا — جتھاں ہر شہری، ہر شہر تے قصبے وچ، سروسز تے چیزاں دی تجارت دا اک منصفانہ، محفوظ تے جدید طریقہ حاصل کر سڳھے۔",
    "about.why.trust.title": "بھروسہ تے تحفظ",
    "about.why.trust.text": "ہر ویچݨ آلا تے دکان کجھ وی لسٹ کرݨ کنوں پہلوں CNIC تے لائیو سیلفی چیک نال تصدیق شدہ تھیندے ہن۔",
    "about.why.community.title": "ودھݨ آلی کمیونٹی",
    "about.why.community.text": "سارے پاکستان وچ ہزاراں خریدار تے ویچݨ آلے، مقامی الیکٹریشناں کنوں شہر بھر دیاں دکاناں تئیں۔",
    "about.why.pakistan.title": "سارا پاکستان",
    "about.why.pakistan.text": "پنہوں شہر تے محلے وچ سروسز یا پراڈکٹ لبھو تے لسٹ کرو۔",
    "about.why.fair.title": "سبھناں کیتے منصفانہ",
    "about.why.fair.text": "شفاف کمیشن، واضح آرڈر ٹریکنگ، تے اک ہیلپ سینٹر جیڑھا سچ مچ جواب ڈیندا اے۔",

